def execute_sql(session_id, sql_text, request_context=None, max_rows_sample=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0311000" if __import__("os").path.isdir("./environment_mix/0311000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _make_id(prefix, existing_ids):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        seed = hashlib.sha256(f"{time.time_ns()}:{len(existing_ids)}:{prefix}".encode("utf-8")).digest()
        out = []
        for b in seed:
            out.append(alphabet[b % 32])
            if len(out) >= 26:
                break
        return f"{prefix}_{''.join(out)}"

    def _sanitize_error_message(msg):
        if msg is None:
            return None
        if not isinstance(msg, str):
            msg = str(msg)
        s = msg
        s = re.sub(r"(?i)(password|pwd)\s*=\s*[^;,\s]+", r"\1=[REDACTED]", s)
        s = re.sub(r"(?i)(access[_-]?token|bearer)\s*[:=]\s*([A-Za-z0-9\-_\.=]+)", r"\1:[REDACTED]", s)
        s = re.sub(r"(?i)(client_secret)\s*=\s*[^;,\s]+", r"\1=[REDACTED]", s)
        s = re.sub(r"(?i)(connection\s*string)\s*[:=]\s*.+", r"\1:[REDACTED]", s)
        s = re.sub(r"(?i)(vault://[^\s]+)", r"[REDACTED_SECRET_REF]", s)
        if len(s) > 2000:
            s = s[:2000] + "…"
        return s

    def _sql_fingerprint(sql):
        if not isinstance(sql, str):
            sql = str(sql)
        s = re.sub(r"/\*.*?\*/", " ", sql, flags=re.S)
        s = re.sub(r"--[^\n]*", " ", s)
        s = re.sub(r"\s+", " ", s).strip().lower()
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log_request(endpoint, status, api_key_id=None, workspace_id=None, error_code=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{time.time_ns()}:{endpoint}:{workspace_id}:{api_key_id}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(_now()),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(session_id, str) or re.match(r"^mcp_sess_[0-9A-HJKMNP-TV-Z]{10,}$", session_id) is None:
        _log_request("execute_sql", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "session_id must be a valid mcp_sess_ ULID")
    if not isinstance(sql_text, str) or len(sql_text.strip()) < 1:
        _log_request("execute_sql", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sql_text must be a non-empty string")
    if request_context is not None and not isinstance(request_context, dict):
        _log_request("execute_sql", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "request_context must be an object")
    if max_rows_sample is not None:
        if not isinstance(max_rows_sample, int) or max_rows_sample < 0:
            _log_request("execute_sql", "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "max_rows_sample must be an integer >= 0")

    # Load core data
    sessions = _load("sessions.json")
    sessions = sessions if isinstance(sessions, list) else []
    workspaces = _load("workspaces.json")
    workspaces = workspaces if isinstance(workspaces, list) else []
    api_keys = _load("api_keys.json")
    api_keys = api_keys if isinstance(api_keys, list) else []
    datasources = _load("datasources.json")
    datasources = datasources if isinstance(datasources, list) else []
    sql_execs = _load("sql_executions.json")
    sql_execs = sql_execs if isinstance(sql_execs, list) else []

    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    # Must create sql_executions row before any "db call" (we don't actually connect; we still record)
    existing_ids = {r.get("id") for r in sql_execs if isinstance(r, dict)}
    sqlx_id = _make_id("mcp_sqlx", existing_ids)

    now = _now()
    exec_row = {
        "id": sqlx_id,
        "workspace_id": sess.get("workspace_id") if isinstance(sess, dict) else None,
        "session_id": session_id,
        "datasource_id": None,
        "tool_name": "execute_sql",
        "status": "queued",
        "sql_text": sql_text,
        "sql_fingerprint": _sql_fingerprint(sql_text),
        "request_context": request_context if isinstance(request_context, dict) else None,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "rows_affected": None,
        "result_set_count": None,
        "result_columns": None,
        "result_rows_sample": None,
        "result_truncated": False,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    sql_execs.append(exec_row)
    _save("sql_executions.json", sql_execs)

    # Helper to fail and persist transition(s)
    transitions = {
        "queued": set(["running", "cancelled", "failed"]),
        "running": set(["succeeded", "failed", "cancelled"]),
        "succeeded": set([]),
        "failed": set([]),
        "cancelled": set([]),
    }

    def _set_status(row, new_status, **updates):
        cur = row.get("status")
        if cur == new_status:
            row.update(updates)
            row["updated_at"] = _iso(_now())
            return True
        if new_status not in transitions.get(cur, set()):
            return False
        row["status"] = new_status
        row.update(updates)
        row["updated_at"] = _iso(_now())
        return True

    def _persist_row():
        # Update in list then save
        for i, r in enumerate(sql_execs):
            if isinstance(r, dict) and r.get("id") == sqlx_id:
                sql_execs[i] = exec_row
                break
        _save("sql_executions.json", sql_execs)

    # Resolve session / workspace / key context
    if not isinstance(sess, dict):
        _set_status(exec_row, "failed", finished_at=_iso(_now()), error_message="session not found")
        _persist_row()
        _log_request("execute_sql", "error", error_code="NOT_FOUND", extra={"sql_execution_id": sqlx_id})
        return _err("NOT_FOUND", "session_id not found", sql_execution_id=sqlx_id)

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == sess.get("workspace_id")), None)
    if not isinstance(ws, dict):
        _set_status(exec_row, "failed", finished_at=_iso(_now()), error_message="workspace not found")
        _persist_row()
        _log_request("execute_sql", "error", workspace_id=sess.get("workspace_id"), error_code="NOT_FOUND", extra={"sql_execution_id": sqlx_id})
        return _err("NOT_FOUND", "workspace not found for session", sql_execution_id=sqlx_id)

    key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == sess.get("api_key_id")), None)
    api_key_id = key.get("id") if isinstance(key, dict) else None

    # Enforce key scope
    scopes = key.get("scopes") if isinstance(key, dict) else None
    if not (isinstance(scopes, list) and "execute_sql" in scopes):
        _set_status(exec_row, "failed", finished_at=_iso(_now()), error_message="api key missing required scope execute_sql")
        _persist_row()
        _log_request("execute_sql", "error", api_key_id=api_key_id, workspace_id=ws.get("id"), error_code="UNAUTHORIZED", extra={"sql_execution_id": sqlx_id})
        return _err("UNAUTHORIZED", "API key missing required scope: execute_sql", sql_execution_id=sqlx_id)

    # Update api key last_used_at on successful auth context resolution
    if isinstance(key, dict):
        key["last_used_at"] = _iso(_now())
        key["updated_at"] = _iso(_now())
        for i, r in enumerate(api_keys):
            if isinstance(r, dict) and r.get("id") == key["id"]:
                api_keys[i] = key
                break
        _save("api_keys.json", api_keys)

    # Session must be active and not expired
    exp = _parse_dt(sess.get("expires_at"))
    if sess.get("status") != "active" or exp is None or _now() >= exp:
        # mark session expired if time passed
        if exp is not None and _now() >= exp and sess.get("status") == "active":
            sess["status"] = "expired"
            sess["updated_at"] = _iso(_now())
            for i, r in enumerate(sessions):
                if isinstance(r, dict) and r.get("id") == sess.get("id"):
                    sessions[i] = sess
                    break
            _save("sessions.json", sessions)

        _set_status(exec_row, "failed", finished_at=_iso(_now()), error_message="session is not active or is expired")
        _persist_row()
        _log_request("execute_sql", "error", api_key_id=api_key_id, workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", extra={"sql_execution_id": sqlx_id})
        return _err("VALIDATION_ERROR", "session cannot be used for execute_sql: session is not active or is expired", sql_execution_id=sqlx_id)

    # Policy safety checks (basic denylist)
    sql_upper = sql_text.upper()
    deny = ["DROP ", "TRUNCATE ", "ALTER LOGIN", "CREATE LOGIN"]
    if any(tok in sql_upper for tok in deny):
        _set_status(exec_row, "failed", finished_at=_iso(_now()), error_message="statement rejected by workspace safety policy")
        _persist_row()
        _log_request("execute_sql", "error", api_key_id=api_key_id, workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", extra={"sql_execution_id": sqlx_id})
        return _err("VALIDATION_ERROR", "statement rejected by workspace safety policy", sql_execution_id=sqlx_id)

    # Concurrency limit
    inflight = 0
    for r in sql_execs:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") == ws.get("id") and r.get("status") in ("queued", "running"):
            inflight += 1
    if inflight > 10:  # includes current queued row we already added
        _set_status(exec_row, "failed", finished_at=_iso(_now()), error_message="workspace concurrency limit exceeded")
        _persist_row()
        _log_request("execute_sql", "error", api_key_id=api_key_id, workspace_id=ws.get("id"), error_code="RATE_LIMIT", extra={"sql_execution_id": sqlx_id})
        return _err("RATE_LIMIT", "Too many concurrent executions for workspace", sql_execution_id=sqlx_id)

    # Resolve datasource: session.datasource_id else workspace.default_datasource_id
    dsid = sess.get("datasource_id") or ws.get("default_datasource_id")
    if not dsid:
        _set_status(exec_row, "failed", finished_at=_iso(_now()), error_message="missing datasource: session has none and workspace has no default_datasource_id")
        _persist_row()
        _log_request("execute_sql", "error", api_key_id=api_key_id, workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", extra={"sql_execution_id": sqlx_id})
        return _err("VALIDATION_ERROR", "No datasource configured for session or workspace default", sql_execution_id=sqlx_id)

    ds = next((d for d in datasources if isinstance(d, dict) and d.get("id") == dsid), None)
    if not isinstance(ds, dict) or ds.get("workspace_id") != ws.get("id"):
        _set_status(exec_row, "failed", finished_at=_iso(_now()), error_message="datasource not found in workspace")
        _persist_row()
        _log_request("execute_sql", "error", api_key_id=api_key_id, workspace_id=ws.get("id"), error_code="NOT_FOUND", extra={"sql_execution_id": sqlx_id})
        return _err("NOT_FOUND", "datasource not found for workspace", sql_execution_id=sqlx_id)

    exec_row["datasource_id"] = ds.get("id")
    exec_row["updated_at"] = _iso(_now())
    _persist_row()

    if ds.get("status") != "active":
        _set_status(exec_row, "failed", finished_at=_iso(_now()), error_message="datasource is not active")
        _persist_row()
        _log_request("execute_sql", "error", api_key_id=api_key_id, workspace_id=ws.get("id"), error_code="VALIDATION_ERROR", extra={"sql_execution_id": sqlx_id})
        return _err("VALIDATION_ERROR", "datasource is not active", sql_execution_id=sqlx_id)

    # Transition queued->running
    start = _now()
    if not _set_status(exec_row, "running", started_at=_iso(start)):
        _set_status(exec_row, "failed", finished_at=_iso(_now()), error_message="invalid execution status transition")
        _persist_row()
        _log_request("execute_sql", "error", api_key_id=api_key_id, workspace_id=ws.get("id"), error_code="INVALID_TRANSITION", extra={"sql_execution_id": sqlx_id})
        return _err("INVALID_TRANSITION", "invalid sql_executions status transition", sql_execution_id=sqlx_id)
    _persist_row()

    # Offline environment: no real SQL Server execution available.
    # Mark failed with sanitized message.
    finished = _now()
    dur = int((finished - start).total_seconds() * 1000)
    msg = _sanitize_error_message("SQL execution not available in offline datastore mode")
    _set_status(
        exec_row,
        "failed",
        finished_at=_iso(finished),
        duration_ms=max(0, dur),
        error_code="OFFLINE",
        error_message=msg,
        result_set_count=0,
        result_columns=[],
        result_rows_sample=[],
        result_truncated=False,
    )
    _persist_row()

    _log_request("execute_sql", "error", api_key_id=api_key_id, workspace_id=ws.get("id"), error_code="UNAUTHORIZED", extra={"sql_execution_id": sqlx_id})
    return _err("UNAUTHORIZED", "SQL execution backend not available in offline mode", sql_execution_id=sqlx_id)

def get_current_identity(api_key, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0311000" if __import__("os").path.isdir("./environment_mix/0311000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_id=None, workspace_id=None, meta=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "mcp_req_" + hashlib.sha256((endpoint + now + str(len(logs))).encode("utf-8")).hexdigest()[:26].upper(),
            "endpoint": endpoint,
            "status": status,
            "credential_id": credential_id,
            "workspace_id": workspace_id,
            "latency_ms": latency_ms,
            "timestamp": now,
        }
        if meta is not None:
            row["meta"] = meta
        if error is not None:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_ts(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
            else:
                dt = datetime.datetime.fromisoformat(s)
            return dt
        except Exception:
            return None

    # Validate
    if not isinstance(api_key, str) or len(api_key) < 8:
        _log("get_current_identity", "error", error={"code": "VALIDATION_ERROR", "message": "api_key invalid"})
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8")

    keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    if not isinstance(keys, list) or not isinstance(workspaces, list):
        _log("get_current_identity", "error", error={"code": "CONFLICT", "message": "Datastore corrupted"})
        return _err("CONFLICT", "Datastore is in an invalid state")

    # Authenticate by matching against client-visible value or id.
    # Store has only key_hash; do NOT compare to it. We accept api_key as id here (client-visible id).
    key = next((k for k in keys if isinstance(k, dict) and (k.get("id") == api_key)), None)
    if key is None:
        _log("get_current_identity", "error", error={"code": "UNAUTHORIZED", "message": "Invalid API key"})
        return _err("UNAUTHORIZED", "Invalid API key")

    if key.get("status") != "active":
        _log("get_current_identity", "error", credential_id=key.get("id"), workspace_id=key.get("workspace_id"), error={"code": "UNAUTHORIZED", "message": "API key revoked"})
        return _err("UNAUTHORIZED", "API key is revoked")
    exp = _parse_ts(key.get("expires_at"))
    if exp is not None and datetime.datetime.utcnow() >= exp:
        _log("get_current_identity", "error", credential_id=key.get("id"), workspace_id=key.get("workspace_id"), error={"code": "UNAUTHORIZED", "message": "API key expired"})
        return _err("UNAUTHORIZED", "API key is expired")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == key.get("workspace_id")), None)
    if ws is None or ws.get("status") != "active":
        _log("get_current_identity", "error", credential_id=key.get("id"), workspace_id=key.get("workspace_id"), error={"code": "UNAUTHORIZED", "message": "Workspace unavailable"})
        return _err("UNAUTHORIZED", "Workspace is not available")

    # Update last_used_at
    key["last_used_at"] = now
    key["updated_at"] = now
    for i, r in enumerate(keys):
        if isinstance(r, dict) and r.get("id") == key.get("id"):
            keys[i] = key
            break
    _save("api_keys.json", keys)

    # Basic consumption summary from request_logs if present
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    key_calls_24h = 0
    ws_calls_24h = 0
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(hours=24)
    for r in logs:
        if not isinstance(r, dict):
            continue
        ts = r.get("timestamp")
        try:
            dt = _parse_ts(ts)
        except Exception:
            dt = None
        if dt is None or dt < cutoff:
            continue
        if r.get("credential_id") == key.get("id"):
            key_calls_24h += 1
        if r.get("workspace_id") == ws.get("id"):
            ws_calls_24h += 1

    _log("get_current_identity", "ok", credential_id=key.get("id"), workspace_id=ws.get("id"))

    return {
        "identity": {
            "api_key_id": key.get("id"),
            "api_key_name": key.get("name"),
            "workspace": {"id": ws.get("id"), "name": ws.get("name"), "status": ws.get("status")},
            "scopes": key.get("scopes") if isinstance(key.get("scopes"), list) else [],
            "expires_at": key.get("expires_at"),
            "last_used_at": key.get("last_used_at"),
        },
        "usage": {
            "calls_last_24h": {"api_key": key_calls_24h, "workspace": ws_calls_24h}
        },
    }

def create_session(api_key, datasource_id=None, client_info=None, ttl_seconds=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0311000" if __import__("os").path.isdir("./environment_mix/0311000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _log(endpoint, status, api_key_id=None, workspace_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + hashlib.sha256(f"{time.time_ns()}:{endpoint}:{workspace_id}:{api_key_id}".encode("utf-8")).hexdigest()[:24],
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _iso(_now()),
            }
        )
        _save("request_logs.json", logs)

    def _make_id(prefix, existing_ids):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        seed = hashlib.sha256(f"{time.time_ns()}:{len(existing_ids)}:{prefix}".encode("utf-8")).digest()
        out = []
        for b in seed:
            out.append(alphabet[b % 32])
            if len(out) >= 26:
                break
        return f"{prefix}_{''.join(out)}"

    # Validate
    if not isinstance(api_key, str) or len(api_key) < 8:
        _log("create_session", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8")
    if datasource_id is not None and (not isinstance(datasource_id, str) or re.match(r"^mcp_ds_[0-9A-HJKMNP-TV-Z]{10,}$", datasource_id) is None):
        _log("create_session", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "datasource_id must be a valid mcp_ds_ ULID")
    if client_info is not None and not isinstance(client_info, dict):
        _log("create_session", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "client_info must be an object")
    if ttl_seconds is not None and (not isinstance(ttl_seconds, int) or ttl_seconds < 60 or ttl_seconds > 86400):
        _log("create_session", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "ttl_seconds must be an integer between 60 and 86400")

    api_keys = _load("api_keys.json")
    api_keys = api_keys if isinstance(api_keys, list) else []
    keyrow = next((k for k in api_keys if isinstance(k, dict) and (k.get("id") == api_key)), None)
    if not isinstance(keyrow, dict):
        _log("create_session", "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "invalid api_key")
    if keyrow.get("status") != "active":
        _log("create_session", "error", api_key_id=keyrow.get("id"), workspace_id=keyrow.get("workspace_id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is not active")

    exp = _parse_dt(keyrow.get("expires_at"))
    if exp is not None and _now() >= exp:
        _log("create_session", "error", api_key_id=keyrow.get("id"), workspace_id=keyrow.get("workspace_id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is expired")

    scopes = keyrow.get("scopes")
    if not (isinstance(scopes, list) and "execute_sql" in scopes):
        _log("create_session", "error", api_key_id=keyrow.get("id"), workspace_id=keyrow.get("workspace_id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key missing required scope: execute_sql")

    workspaces = _load("workspaces.json")
    workspaces = workspaces if isinstance(workspaces, list) else []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == keyrow.get("workspace_id")), None)
    if not isinstance(ws, dict):
        _log("create_session", "error", api_key_id=keyrow.get("id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "workspace not found for api_key")

    # Workspace may be suspended; treat as unauthorized only if no valid combo exists.
    # Here request is explicitly for this api_key/workspace; refuse if deleted.
    if ws.get("status") == "deleted":
        _log("create_session", "error", api_key_id=keyrow.get("id"), workspace_id=ws.get("id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "workspace is deleted")

    # Validate datasource belongs to workspace (if specified)
    if datasource_id is not None:
        datasources = _load("datasources.json")
        datasources = datasources if isinstance(datasources, list) else []
        ds = next((d for d in datasources if isinstance(d, dict) and d.get("id") == datasource_id), None)
        if not isinstance(ds, dict) or ds.get("workspace_id") != ws.get("id"):
            _log("create_session", "error", api_key_id=keyrow.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "datasource_id is not in the authenticated workspace")
    now = _now()
    ttl = ttl_seconds if ttl_seconds is not None else 3600
    expires_at = now + datetime.timedelta(seconds=int(ttl))

    sessions = _load("sessions.json")
    sessions = sessions if isinstance(sessions, list) else []
    existing_ids = {r.get("id") for r in sessions if isinstance(r, dict)}
    sess_id = _make_id("mcp_sess", existing_ids)

    sess_row = {
        "id": sess_id,
        "workspace_id": ws.get("id"),
        "api_key_id": keyrow.get("id"),
        "datasource_id": datasource_id,
        "status": "active",
        "client_info": client_info if isinstance(client_info, dict) else None,
        "issued_at": _iso(now),
        "expires_at": _iso(expires_at),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    sessions.append(sess_row)
    _save("sessions.json", sessions)

    # Update key last_used_at
    keyrow["last_used_at"] = _iso(_now())
    keyrow["updated_at"] = _iso(_now())
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == keyrow.get("id"):
            api_keys[i] = keyrow
            break
    _save("api_keys.json", api_keys)

    _log("create_session", "ok", api_key_id=keyrow.get("id"), workspace_id=ws.get("id"))
    return {"session": sess_row}

def revoke_session(api_key, session_id, reason=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0311000" if __import__("os").path.isdir("./environment_mix/0311000") else "/app/database")

