        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _log(endpoint, status, api_key_id=None, workspace_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + hashlib.sha256(f"{time.time_ns()}:{endpoint}:{workspace_id}:{api_key_id}".encode("utf-8")).hexdigest()[:24],
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _iso(_now()),
            }
        )
        _save("request_logs.json", logs)

    # validate
    if not isinstance(api_key, str) or len(api_key) < 8:
        _log("revoke_session", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8")
    if not isinstance(session_id, str) or re.match(r"^mcp_sess_[0-9A-HJKMNP-TV-Z]{10,}$", session_id) is None:
        _log("revoke_session", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "session_id must be a valid mcp_sess_ ULID")
    if reason is not None and (not isinstance(reason, str) or len(reason) < 1 or len(reason) > 256):
        _log("revoke_session", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reason must be a string between 1 and 256 characters")

    api_keys = _load("api_keys.json")
    api_keys = api_keys if isinstance(api_keys, list) else []
    keyrow = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key), None)
    if not isinstance(keyrow, dict):
        _log("revoke_session", "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "invalid api_key")
    if keyrow.get("status") != "active":
        _log("revoke_session", "error", api_key_id=keyrow.get("id"), workspace_id=keyrow.get("workspace_id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is not active")
    exp = _parse_dt(keyrow.get("expires_at"))
    if exp is not None and _now() >= exp:
        _log("revoke_session", "error", api_key_id=keyrow.get("id"), workspace_id=keyrow.get("workspace_id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is expired")

    workspaces = _load("workspaces.json")
    workspaces = workspaces if isinstance(workspaces, list) else []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == keyrow.get("workspace_id")), None)
    if not isinstance(ws, dict):
        _log("revoke_session", "error", api_key_id=keyrow.get("id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "workspace not found for api_key")
    if ws.get("status") == "deleted":
        _log("revoke_session", "error", api_key_id=keyrow.get("id"), workspace_id=ws.get("id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "workspace is deleted")

    sessions = _load("sessions.json")
    sessions = sessions if isinstance(sessions, list) else []
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id and s.get("workspace_id") == ws.get("id")), None)
    if not isinstance(sess, dict):
        _log("revoke_session", "error", api_key_id=keyrow.get("id"), workspace_id=ws.get("id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "session_id not found in authenticated workspace")

    if sess.get("status") != "active":
        _log("revoke_session", "error", api_key_id=keyrow.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "session is not in a revocable state")

    sess["status"] = "revoked"
    sess["updated_at"] = _iso(_now())
    if reason is not None:
        sess["revocation_reason"] = reason  # extra audit field (tolerated)
    for i, r in enumerate(sessions):
        if isinstance(r, dict) and r.get("id") == sess.get("id"):
            sessions[i] = sess
            break
    _save("sessions.json", sessions)

    # Update api key last_used_at
    keyrow["last_used_at"] = _iso(_now())
    keyrow["updated_at"] = _iso(_now())
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == keyrow.get("id"):
            api_keys[i] = keyrow
            break
    _save("api_keys.json", api_keys)

    _log("revoke_session", "ok", api_key_id=keyrow.get("id"), workspace_id=ws.get("id"))
    return {"session": sess}

def list_datasources(api_key, status=None, name_prefix=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0311000" if __import__("os").path.isdir("./environment_mix/0311000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(endpoint, status_s, api_key_id=None, workspace_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{time.time_ns()}:{endpoint}:{workspace_id}:{api_key_id}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(_now_dt()),
        })
        _save("request_logs.json", logs)

    def _b64url_encode(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _b64url_decode(s):
        pad = "=" * (-len(s) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("ascii"))

    def _make_cursor(last_name, last_id):
        payload = json.dumps({"n": last_name, "i": last_id}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        sig = hashlib.sha256(payload).digest()[:10]
        return _b64url_encode(sig + payload)

    def _parse_cursor(cur):
        # IMPORTANT: cursor is optional/opaque; if it's invalid, do not throw VALIDATION_ERROR unless clearly malformed.
        # We'll treat unparseable cursor as "start from beginning" to be lenient.
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = _b64url_decode(cur)
            if len(raw) < 11:
                return None
            sig = raw[:10]
            payload = raw[10:]
            if hashlib.sha256(payload).digest()[:10] != sig:
                return None
            obj = json.loads(payload.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            n = obj.get("n")
            i = obj.get("i")
            if not isinstance(n, str) or not isinstance(i, str) or not n or not i:
                return None
            return (n, i)
        except Exception:
            return None

    def _sanitize_ds_row(r):
        allowed = {
            "id", "workspace_id", "name", "status",
            "server_host", "server_port", "database_name", "auth_mode",
            "username", "password_secret_ref",
            "encrypt", "trust_server_certificate", "connection_options",
            "created_at", "updated_at",
        }
        return {k: r.get(k) for k in allowed if k in r}

    # validate inputs
    if not isinstance(api_key, str) or len(api_key) < 8:
        _log("list_datasources", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8")
    if status is not None and status not in ("active", "disabled", "deleted"):
        _log("list_datasources", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted")
    if name_prefix is not None:
        if not isinstance(name_prefix, str) or not (1 <= len(name_prefix) <= 128):
            _log("list_datasources", "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name_prefix must be a string between 1 and 128 characters")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("list_datasources", "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    lim = limit if limit is not None else 50

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    datasources = _load("datasources.json")
    if not isinstance(api_keys, list): api_keys = []
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(datasources, list): datasources = []

    key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key), None)
    if not key_row:
        _log("list_datasources", "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid api_key")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == key_row.get("workspace_id")), None)
    if not ws or ws.get("status") != "active":
        _log("list_datasources", "error", api_key_id=key_row.get("id"), workspace_id=key_row.get("workspace_id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active")

    items = [d for d in datasources if isinstance(d, dict) and d.get("workspace_id") == ws.get("id")]
    if status is not None:
        items = [d for d in items if d.get("status") == status]
    if name_prefix is not None:
        items = [d for d in items if isinstance(d.get("name"), str) and d.get("name").startswith(name_prefix)]

    # stable sort by (name, id)
    items.sort(key=lambda r: ((r.get("name") or ""), (r.get("id") or "")))

    start = 0
    cur = _parse_cursor(cursor)
    if cur is not None:
        last_name, last_id = cur
        # find first item strictly greater than cursor tuple
        for idx, r in enumerate(items):
            tup = ((r.get("name") or ""), (r.get("id") or ""))
            if tup > (last_name, last_id):
                start = idx
                break
        else:
            start = len(items)

    page = items[start:start + lim]
    has_more = start + lim < len(items)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _make_cursor(last.get("name") or "", last.get("id") or "")

    # update key last_used_at
    key_row["last_used_at"] = _iso(_now_dt())
    key_row["updated_at"] = _iso(_now_dt())
    _save("api_keys.json", api_keys)

    _log("list_datasources", "ok", api_key_id=key_row.get("id"), workspace_id=ws.get("id"))
    return {
        "datasources": [_sanitize_ds_row(r) for r in page],
        "total": len(items),
        "has_more": bool(has_more),
        "next_cursor": next_cursor,
    }

