        return _err("UNAUTHORIZED", "Workspace is not active")

    # uniqueness constraint: unique(workspace_id, name)
    if any(isinstance(d, dict) and d.get("workspace_id") == ws.get("id") and d.get("name") == name for d in datasources):
        _log("create_datasource", "error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), error_code="CONFLICT")
        return _err("CONFLICT", "Datasource name already exists in workspace")

    # map tool auth modes to datastore enum
    if auth_mode == "azure_ad_password":
        store_auth_mode = "azure_ad"
        # requires username/password_secret_ref in datastore; we will create secret_ref from supplied password
        if not isinstance(username, str) or not username:
            _log("create_datasource", "error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "username is required for azure_ad_password")
        if not isinstance(password, str) or not password:
            _log("create_datasource", "error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "password is required for azure_ad_password")
        password_secret_ref = "vault://inline/azure_ad_password/" + hashlib.sha256((ws.get("id", "") + ":" + name + ":" + password).encode("utf-8")).hexdigest()[:32]
    elif auth_mode == "azure_ad_integrated":
        store_auth_mode = "azure_ad"
        password_secret_ref = None
        # username optional
    elif auth_mode == "windows":
        store_auth_mode = "windows"
        password_secret_ref = None
    else:
        store_auth_mode = "sql_login"
        if not isinstance(username, str) or not username:
            _log("create_datasource", "error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "username is required for sql_login")
        if not isinstance(password, str) or not password:
            _log("create_datasource", "error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "password is required for sql_login")
        password_secret_ref = "vault://inline/sql_login/" + hashlib.sha256((ws.get("id", "") + ":" + name + ":" + password).encode("utf-8")).hexdigest()[:32]

    # defaults
    if server_port is None:
        server_port = 1433
    if encrypt is None:
        encrypt = True
    if trust_server_certificate is None:
        trust_server_certificate = False

    now = _now_dt()
    ds_id = _make_id("mcp_ds", [d.get("id") for d in datasources if isinstance(d, dict)])
    ds = {
        "id": ds_id,
        "workspace_id": ws.get("id"),
        "name": name,
        "status": "active",
        "server_host": server_host,
        "server_port": int(server_port),
        "database_name": database_name,
        "auth_mode": store_auth_mode,
        "username": username if isinstance(username, str) else None,
        "password_secret_ref": password_secret_ref,
        "encrypt": bool(encrypt),
        "trust_server_certificate": bool(trust_server_certificate),
        "connection_options": connection_options if isinstance(connection_options, dict) else None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    # datastore constraint: auth_mode='sql_login' => username and password_secret_ref required
    if ds["auth_mode"] == "sql_login" and (not ds["username"] or not ds["password_secret_ref"]):
        _log("create_datasource", "error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sql_login requires username and password")

    datasources.append(ds)
    _save("datasources.json", datasources)

    # optionally set workspace default
    if set_as_workspace_default:
        ws["default_datasource_id"] = ds_id
        ws["updated_at"] = _iso(_now_dt())
        _save("workspaces.json", workspaces)

    # update key last_used_at
    key_row["last_used_at"] = _iso(_now_dt())
    key_row["updated_at"] = _iso(_now_dt())
    _save("api_keys.json", api_keys)

    _log("create_datasource", "ok", api_key_id=key_row.get("id"), workspace_id=ws.get("id"))
    return {"datasource": _sanitize_ds_row(ds)}

def update_datasource_status(api_key, datasource_id, status, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0311000" if __import__("os").path.isdir("./environment_mix/0311000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _log(endpoint, status_s, api_key_id=None, workspace_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + hashlib.sha256(f"{time.time_ns()}:{endpoint}:{workspace_id}:{api_key_id}".encode("utf-8")).hexdigest()[:24],
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _iso(_now()),
            }
        )
        _save("request_logs.json", logs)

    # validate
    if not isinstance(api_key, str) or len(api_key) < 8:
        _log("update_datasource_status", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8")
    if not isinstance(datasource_id, str) or re.match(r"^mcp_ds_[0-9A-HJKMNP-TV-Z]{10,}$", datasource_id) is None:
        _log("update_datasource_status", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "datasource_id must be a valid mcp_ds_ ULID")
    if status not in ("active", "disabled", "deleted"):
        _log("update_datasource_status", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted")

    api_keys = _load("api_keys.json")
    api_keys = api_keys if isinstance(api_keys, list) else []
    keyrow = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key), None)
    if not isinstance(keyrow, dict):
        _log("update_datasource_status", "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "invalid api_key")
    if keyrow.get("status") != "active":
        _log("update_datasource_status", "error", api_key_id=keyrow.get("id"), workspace_id=keyrow.get("workspace_id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is not active")

    exp = _parse_dt(keyrow.get("expires_at"))
    if exp is not None and _now() >= exp:
        _log("update_datasource_status", "error", api_key_id=keyrow.get("id"), workspace_id=keyrow.get("workspace_id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is expired")

    workspaces = _load("workspaces.json")
    workspaces = workspaces if isinstance(workspaces, list) else []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == keyrow.get("workspace_id")), None)
    if not isinstance(ws, dict):
        _log("update_datasource_status", "error", api_key_id=keyrow.get("id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "workspace not found for api_key")
    if ws.get("status") == "deleted":
        _log("update_datasource_status", "error", api_key_id=keyrow.get("id"), workspace_id=ws.get("id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "workspace is deleted")

    datasources = _load("datasources.json")
    datasources = datasources if isinstance(datasources, list) else []
    ds = next((d for d in datasources if isinstance(d, dict) and d.get("id") == datasource_id and d.get("workspace_id") == ws.get("id")), None)
    if not isinstance(ds, dict):
        _log("update_datasource_status", "error", api_key_id=keyrow.get("id"), workspace_id=ws.get("id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "datasource_id not found in authenticated workspace")

    transitions = {
        "active": set(["disabled", "deleted"]),
        "disabled": set(["active", "deleted"]),
        "deleted": set([]),
    }
    cur = ds.get("status")
    if status == cur:
        # idempotent no-op is allowed only if it matches a real row; return updated row and persist timestamp touch
        ds["updated_at"] = _iso(_now())
    else:
        if status not in transitions.get(cur, set()):
            _log("update_datasource_status", "error", api_key_id=keyrow.get("id"), workspace_id=ws.get("id"), error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"invalid datasource status transition: {cur} -> {status}")
        ds["status"] = status
        ds["updated_at"] = _iso(_now())

    for i, r in enumerate(datasources):
        if isinstance(r, dict) and r.get("id") == ds.get("id"):
            datasources[i] = ds
            break
    _save("datasources.json", datasources)

    # Update api key last_used_at
    keyrow["last_used_at"] = _iso(_now())
    keyrow["updated_at"] = _iso(_now())
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == keyrow.get("id"):
            api_keys[i] = keyrow
            break
    _save("api_keys.json", api_keys)

    _log("update_datasource_status", "ok", api_key_id=keyrow.get("id"), workspace_id=ws.get("id"))
    return {"datasource": ds}
